<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Validator;
use Carbon\Carbon;

class MainController extends Controller {
 private function log($action,$desc=null,$type=null,$id=null){DB::table('activity_logs')->insert(['user_id'=>Auth::id(),'action'=>$action,'description'=>$desc,'subject_type'=>$type,'subject_id'=>$id,'ip_address'=>request()->ip(),'created_at'=>now(),'updated_at'=>now()]);}
 public function dashboard(){
  $role=Auth::user()->role;
  if($role==='buyer') return redirect()->route('shop');
  if($role==='courier'){
   $stats=['Siap diantar'=>DB::table('deliveries')->where('status','waiting')->count(),'Sedang diantar'=>DB::table('deliveries')->where('courier_id',Auth::id())->where('status','in_transit')->count(),'Selesai hari ini'=>DB::table('deliveries')->where('courier_id',Auth::id())->whereDate('delivered_at',today())->count(),'Notifikasi'=>DB::table('notifications')->where('user_id',Auth::id())->whereNull('read_at')->count()];
   return view('dashboard',compact('stats','role'));
  }
  if($role==='employee'){
   $stats=['Produk perlu dicek'=>DB::table('product_batches')->whereDate('expiry_date','<=',now()->addDays(30))->where('quantity','>',0)->count(),'Mendekati kedaluwarsa'=>DB::table('product_batches')->whereBetween('expiry_date',[today(),now()->addDays(30)])->where('quantity','>',0)->count(),'Stok kritis'=>DB::table('products')->whereColumn('stock','<=','min_stock')->count(),'Pesanan baru'=>DB::table('orders')->where('status','pending')->count()];
   return view('dashboard',compact('stats','role'));
  }
  return app(\App\Http\Controllers\OwnerController::class)->dashboard();
  $stats=['Produk aktif'=>DB::table('products')->where('is_active',1)->count(),'Total stok'=>DB::table('products')->sum('stock'),'Sudah kedaluwarsa'=>DB::table('product_batches')->whereDate('expiry_date','<',today())->where('quantity','>',0)->count(),'Mendekati kedaluwarsa'=>DB::table('product_batches')->whereBetween('expiry_date',[today(),now()->addDays(30)])->where('quantity','>',0)->count(),'Menunggu konfirmasi'=>DB::table('orders')->where('status','pending')->count(),'Pendapatan bulan ini'=>DB::table('orders')->where('payment_status','paid')->whereMonth('created_at',now()->month)->sum('total'),'Pesanan hari ini'=>DB::table('orders')->whereDate('created_at',today())->count(),'Supplier'=>DB::table('suppliers')->count()];
  $latest=DB::table('orders')->join('users','users.id','=','orders.user_id')->select('orders.*','users.name as buyer')->latest('orders.created_at')->limit(6)->get();
  $expiring=DB::table('product_batches')->join('products','products.id','=','product_batches.product_id')->where('quantity','>',0)->whereDate('expiry_date','<=',now()->addDays(30))->orderBy('expiry_date')->limit(6)->get();
  return view('dashboard',compact('stats','role','latest','expiring'));
 }
 public function shop(Request $r){
  $q=DB::table('products')->join('categories','categories.id','=','products.category_id')->select('products.*','categories.name as category')->where('products.is_active',1);
  if($r->filled('q'))$q->where('products.name','like','%'.$r->q.'%');
  if($r->filled('category'))$q->where('categories.slug',$r->category);
  $products=$q->orderBy('products.name')->paginate(12)->withQueryString();
  $categories=DB::table('categories')->where('is_active',1)->get();
  return view('shop',compact('products','categories'));
 }
 public function product($id){$product=DB::table('products')->leftJoin('categories','categories.id','=','products.category_id')->select('products.*','categories.name as category')->where('products.id',$id)->first();abort_unless($product && $product->is_active,404);return view('product',compact('product'));}
 public function cart(){ $cart=session('cart',[]);$ids=array_keys($cart);$products=DB::table('products')->whereIn('id',$ids)->get()->keyBy('id');return view('cart',compact('cart','products')); }
 public function addCart(Request $r,$id){$p=DB::table('products')->where('id',$id)->where('is_active',1)->first();abort_unless($p,404);$qty=max(1,(int)$r->input('quantity',1));$cart=session('cart',[]);$cart[$id]=min(($cart[$id]??0)+$qty,(int)$p->stock);session(['cart'=>$cart]);return back()->with('success','Produk ditambahkan ke keranjang.');}
 public function updateCart(Request $r){$cart=session('cart',[]);foreach($r->input('qty',[]) as $id=>$qty){$p=DB::table('products')->find($id);if(!$p||$qty<1)unset($cart[$id]);else $cart[$id]=min((int)$qty,(int)$p->stock);}session(['cart'=>$cart]);return back()->with('success','Keranjang diperbarui.');}
 public function removeCart($id){$cart=session('cart',[]);unset($cart[$id]);session(['cart'=>$cart]);return back();}
 public function checkout(){abort_unless(Auth::check() && Auth::user()->role==='buyer',403);$cart=session('cart',[]);abort_if(!$cart,redirect()->route('cart'));$products=DB::table('products')->whereIn('id',array_keys($cart))->get()->keyBy('id');return view('checkout',compact('cart','products'));}
 public function placeOrder(Request $r){
  $d=$r->validate(['shipping_address'=>'required|string|max:1000','phone'=>'required|string|max:30','delivery_method'=>'required|in:pickup,internal,external','payment_method'=>'required|in:cod,transfer,qris','notes'=>'nullable|string|max:1000']);
  $cart=session('cart',[]);abort_if(!$cart,redirect()->route('cart'));
  $orderId=DB::transaction(function()use($cart,$d){
   $subtotal=0;$items=[];foreach($cart as $id=>$qty){$p=DB::table('products')->where('id',$id)->lockForUpdate()->first();if(!$p||!$p->is_active||$p->stock<$qty)throw \Illuminate\Validation\ValidationException::withMessages(['cart'=>'Stok produk '.$p->name.' tidak mencukupi.']);$subtotal+=$p->price*$qty;$items[]=[$p,$qty];}
   $ship=$d['delivery_method']==='internal'?5000:0;$num='CS-'.now()->format('Ymd').'-'.strtoupper(Str::random(5));
   $id=DB::table('orders')->insertGetId(['order_number'=>$num,'user_id'=>Auth::id(),'status'=>'pending','delivery_method'=>$d['delivery_method'],'payment_method'=>$d['payment_method'],'payment_status'=>$d['payment_method']==='cod'?'unpaid':'pending','subtotal'=>$subtotal,'shipping_cost'=>$ship,'total'=>$subtotal+$ship,'shipping_address'=>$d['shipping_address'],'phone'=>$d['phone'],'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);
   foreach($items as [$p,$qty])DB::table('order_details')->insert(['order_id'=>$id,'product_id'=>$p->id,'quantity'=>$qty,'unit_price'=>$p->price,'subtotal'=>$p->price*$qty,'created_at'=>now(),'updated_at'=>now()]);
   DB::table('payments')->insert(['order_id'=>$id,'method'=>$d['payment_method'],'amount'=>$subtotal+$ship,'status'=>$d['payment_method']==='cod'?'unpaid':'pending','created_at'=>now(),'updated_at'=>now()]);
   if($d['delivery_method']==='internal')DB::table('deliveries')->insert(['order_id'=>$id,'status'=>'waiting','created_at'=>now(),'updated_at'=>now()]);
   DB::table('notifications')->insert(['user_id'=>1,'type'=>'order','title'=>'Pesanan baru','body'=>'Pesanan '.$num.' menunggu konfirmasi.','url'=>'/admin/orders','created_at'=>now(),'updated_at'=>now()]);
   return $id;
  });
  session()->forget('cart');return redirect()->route('orders.show',$orderId)->with('success','Pesanan berhasil dibuat.');
 }
 public function orders(){ $orders=DB::table('orders')->where('user_id',Auth::id())->latest()->paginate(10);return view('orders',compact('orders')); }
 public function orderShow($id){$order=DB::table('orders')->where('id',$id)->first();abort_unless($order && ($order->user_id==Auth::id() || in_array(Auth::user()->role,['admin','employee']) || ($order->id && Auth::user()->role==='courier' && DB::table('deliveries')->where('order_id',$id)->where('courier_id',Auth::id())->exists())),403);$items=DB::table('order_details')->join('products','products.id','=','order_details.product_id')->where('order_id',$id)->select('order_details.*','products.name','products.image')->get();$delivery=DB::table('deliveries')->where('order_id',$id)->first();return view('order-show',compact('order','items','delivery'));}
 public function adminProducts(Request $r){$q=DB::table('products')->leftJoin('categories','categories.id','=','products.category_id')->select('products.*','categories.name as category');if($r->filled('q'))$q->where('products.name','like','%'.$r->q.'%');$products=$q->orderByDesc('products.id')->paginate(12)->withQueryString();return view('products',compact('products'));}
 public function productForm($id=null){$product=$id?DB::table('products')->find($id):null;$categories=DB::table('categories')->get();return view('product-form',compact('product','categories'));}
 public function saveProduct(Request $r,$id=null){$d=$r->validate(['name'=>'required|max:160','category_id'=>'nullable|exists:categories,id','sku'=>'required|max:60|unique:products,sku'.($id?','.$id:''),'price'=>'required|numeric|min:0','purchase_price'=>'nullable|numeric|min:0','unit'=>'required|max:30','min_stock'=>'required|integer|min:0','description'=>'nullable|string','image'=>'nullable|image|max:5120']);$d['is_active']=$r->boolean('is_active');if($r->hasFile('image'))$d['image']=$r->file('image')->store('products','public');unset($d['_token']);if($id)DB::table('products')->where('id',$id)->update($d+['updated_at'=>now()]);else DB::table('products')->insert($d+['stock'=>0,'created_at'=>now(),'updated_at'=>now()]);$this->log($id?'update_product':'create_product',$d['name']);return redirect()->route('admin.products')->with('success','Produk berhasil disimpan.');}
 public function deleteProduct($id){DB::table('products')->where('id',$id)->update(['is_active'=>0,'deleted_at'=>now()]);return back()->with('success','Produk dinonaktifkan.');}
 public function batches(Request $r){$q=DB::table('product_batches')->join('products','products.id','=','product_batches.product_id')->leftJoin('suppliers','suppliers.id','=','product_batches.supplier_id')->select('product_batches.*','products.name as product','products.sku','suppliers.name as supplier');if($r->filled('q'))$q->where(fn($x)=>$x->where('products.name','like','%'.$r->q.'%')->orWhere('batch_code','like','%'.$r->q.'%'));if($r->status==='expired')$q->whereDate('expiry_date','<',today());elseif($r->status==='soon')$q->whereBetween('expiry_date',[today(),now()->addDays(30)]);elseif($r->status==='safe')$q->whereDate('expiry_date','>',now()->addDays(30));$batches=$q->orderBy('expiry_date')->paginate(15)->withQueryString();return view('batches',compact('batches'));}
 public function checkBatch($id){DB::table('product_batches')->where('id',$id)->update(['checked_by'=>Auth::id(),'checked_at'=>now(),'updated_at'=>now()]);$this->log('check_expiry','Pemeriksaan batch #'.$id);return back()->with('success','Batch ditandai sudah diperiksa.');}
 public function suppliers(){ $suppliers=DB::table('suppliers')->latest()->paginate(15);return view('suppliers',compact('suppliers')); }
 public function saveSupplier(Request $r){$d=$r->validate(['name'=>'required|max:160','pic'=>'nullable|max:120','phone'=>'nullable|max:30','email'=>'nullable|email','address'=>'nullable|string','notes'=>'nullable|string']);DB::table('suppliers')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Supplier ditambahkan.');}
 public function receiptForm(){return view('receipt-form',['suppliers'=>DB::table('suppliers')->get(),'products'=>DB::table('products')->where('is_active',1)->get()]);}
 public function saveReceipt(Request $r){$d=$r->validate(['supplier_id'=>'required|exists:suppliers,id','product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1','purchase_price'=>'required|numeric|min:0','batch_code'=>'required|max:80','production_date'=>'nullable|date','expiry_date'=>'required|date|after:today','notes'=>'nullable|string']);DB::transaction(function()use($d){$p=DB::table('products')->where('id',$d['product_id'])->lockForUpdate()->first();$rid=DB::table('goods_receipts')->insertGetId(['receipt_number'=>'GR-'.now()->format('ymdHis').'-'.Str::upper(Str::random(3)),'supplier_id'=>$d['supplier_id'],'user_id'=>Auth::id(),'received_at'=>today(),'total'=>$d['quantity']*$d['purchase_price'],'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);$bid=DB::table('product_batches')->insertGetId(['product_id'=>$p->id,'supplier_id'=>$d['supplier_id'],'batch_code'=>$d['batch_code'],'quantity'=>$d['quantity'],'production_date'=>$d['production_date']??null,'received_date'=>today(),'expiry_date'=>$d['expiry_date'],'purchase_price'=>$d['purchase_price'],'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('goods_receipt_details')->insert(['goods_receipt_id'=>$rid,'product_id'=>$p->id,'batch_id'=>$bid,'quantity'=>$d['quantity'],'purchase_price'=>$d['purchase_price'],'created_at'=>now(),'updated_at'=>now()]);DB::table('products')->where('id',$p->id)->increment('stock',$d['quantity']);DB::table('stock_movements')->insert(['product_id'=>$p->id,'batch_id'=>$bid,'user_id'=>Auth::id(),'type'=>'in','quantity'=>$d['quantity'],'balance'=>$p->stock+$d['quantity'],'reference'=>'GR-'.$rid,'notes'=>'Penerimaan barang','created_at'=>now(),'updated_at'=>now()]);});$this->log('goods_receipt','Penerimaan barang disimpan');return redirect()->route('batches')->with('success','Penerimaan tersimpan dan stok bertambah.');}
 public function ordersAdmin(Request $r){$q=DB::table('orders')->join('users','users.id','=','orders.user_id')->select('orders.*','users.name as buyer');if($r->filled('q'))$q->where(fn($x)=>$x->where('order_number','like','%'.$r->q.'%')->orWhere('users.name','like','%'.$r->q.'%'));if($r->filled('status'))$q->where('orders.status',$r->status);$orders=$q->latest('orders.created_at')->paginate(15)->withQueryString();return view('admin-orders',compact('orders'));}
 public function updateOrder(Request $r,$id){$d=$r->validate(['status'=>'required|in:confirmed,processing,packed,ready,completed,cancelled','payment_status'=>'nullable|in:pending,paid,rejected,unpaid']);DB::transaction(function()use($d,$id){$o=DB::table('orders')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);if($d['status']==='confirmed' && $o->status==='pending'){ $details=DB::table('order_details')->where('order_id',$id)->get();foreach($details as $line){$remaining=$line->quantity;$batches=DB::table('product_batches')->where('product_id',$line->product_id)->where('quantity','>',0)->whereDate('expiry_date','>=',today())->orderBy('expiry_date')->lockForUpdate()->get();foreach($batches as $b){if(!$remaining)break;$take=min($remaining,$b->quantity);DB::table('product_batches')->where('id',$b->id)->decrement('quantity',$take);DB::table('stock_movements')->insert(['product_id'=>$line->product_id,'batch_id'=>$b->id,'user_id'=>Auth::id(),'type'=>'out','quantity'=>-$take,'balance'=>$b->quantity-$take,'reference'=>$o->order_number,'notes'=>'FEFO pesanan','created_at'=>now(),'updated_at'=>now()]);$remaining-=$take;}if($remaining>0)throw \Illuminate\Validation\ValidationException::withMessages(['stock'=>'Stok batch tidak mencukupi untuk '.$line->product_id]);DB::table('products')->where('id',$line->product_id)->decrement('stock',$line->quantity);}}
   DB::table('orders')->where('id',$id)->update(['status'=>$d['status'],'payment_status'=>$d['payment_status']??$o->payment_status,'confirmed_at'=>$d['status']==='confirmed'?now():$o->confirmed_at,'completed_at'=>$d['status']==='completed'?now():$o->completed_at,'updated_at'=>now()]);
   if(isset($d['payment_status']))DB::table('payments')->where('order_id',$id)->update(['status'=>$d['payment_status'],'verified_by'=>Auth::id(),'paid_at'=>$d['payment_status']==='paid'?now():null,'updated_at'=>now()]);
   DB::table('notifications')->insert(['user_id'=>$o->user_id,'type'=>'order','title'=>'Status pesanan diperbarui','body'=>'Pesanan '.$o->order_number.' kini '.$d['status'].'.','url'=>'/orders/'.$id,'created_at'=>now(),'updated_at'=>now()]);
  });return back()->with('success','Status pesanan diperbarui.');}
 public function assignCourier(Request $r,$id){$d=$r->validate(['courier_id'=>'required|exists:users,id']);abort_unless(DB::table('users')->where('id',$d['courier_id'])->where('role','courier')->exists(),422);DB::table('deliveries')->updateOrInsert(['order_id'=>$id],['courier_id'=>$d['courier_id'],'status'=>'assigned','assigned_at'=>now(),'updated_at'=>now()]);DB::table('orders')->where('id',$id)->update(['status'=>'ready','updated_at'=>now()]);return back()->with('success','Kurir berhasil ditugaskan.');}
 public function courierOrders(){ $deliveries=DB::table('deliveries')->join('orders','orders.id','=','deliveries.order_id')->join('users','users.id','=','orders.user_id')->select('deliveries.*','orders.order_number','orders.total','orders.shipping_address','users.name as buyer')->where(fn($q)=>$q->whereNull('deliveries.courier_id')->orWhere('deliveries.courier_id',Auth::id()))->orderBy('deliveries.created_at')->get();return view('courier-orders',compact('deliveries')); }
 public function takeDelivery($id){DB::table('deliveries')->where('order_id',$id)->whereNull('courier_id')->update(['courier_id'=>Auth::id(),'status'=>'assigned','assigned_at'=>now(),'updated_at'=>now()]);return back()->with('success','Pesanan ditugaskan kepada Anda.');}
 public function deliveryStatus(Request $r,$id){$d=$r->validate(['status'=>'required|in:in_transit,delivered,failed','courier_note'=>'nullable|string|max:1000']);$delivery=DB::table('deliveries')->where('order_id',$id)->where('courier_id',Auth::id())->first();abort_unless($delivery,403);DB::table('deliveries')->where('id',$delivery->id)->update(['status'=>$d['status'],'courier_note'=>$d['courier_note']??null,'started_at'=>$d['status']==='in_transit'?now():$delivery->started_at,'delivered_at'=>$d['status']==='delivered'?now():null,'updated_at'=>now()]);if($d['status']==='delivered')DB::table('orders')->where('id',$id)->update(['status'=>'completed','completed_at'=>now(),'updated_at'=>now()]);return back()->with('success','Status pengantaran diperbarui.');}
 public function chatIndex(){if(Auth::user()->role==='buyer'){$conversations=DB::table('conversations')->where('buyer_id',Auth::id())->get();}else{$conversations=DB::table('conversations')->join('users','users.id','=','conversations.buyer_id')->select('conversations.*','users.name as buyer')->orderByDesc('last_message_at')->get();}return view('chat-index',compact('conversations'));}
 public function chatOpen(Request $r){$role=Auth::user()->role;if($role==='buyer'){$c=DB::table('conversations')->where('buyer_id',Auth::id())->first();if(!$c){$id=DB::table('conversations')->insertGetId(['buyer_id'=>Auth::id(),'subject'=>'Bantuan pelanggan','status'=>'open','created_at'=>now(),'updated_at'=>now()]);return redirect()->route('chat.show',$id);}return redirect()->route('chat.show',$c->id);}abort_unless(in_array($role,['admin','employee']),403);$id=$r->validate(['conversation_id'=>'required|exists:conversations,id'])['conversation_id'];return redirect()->route('chat.show',$id);}
 public function chatShow($id){$c=DB::table('conversations')->where('id',$id)->first();abort_unless($c && (Auth::user()->role==='buyer'?$c->buyer_id==Auth::id():in_array(Auth::user()->role,['admin','employee']) && (Auth::user()->role==='admin'||Auth::user()->chat_enabled)),403);$messages=DB::table('messages')->join('users','users.id','=','messages.sender_id')->where('conversation_id',$id)->select('messages.*','users.name as sender')->orderBy('messages.id')->get();DB::table('messages')->where('conversation_id',$id)->where('sender_id','!=',Auth::id())->whereNull('read_at')->update(['read_at'=>now()]);$buyer=DB::table('users')->find($c->buyer_id);return view('chat-show',compact('c','messages','buyer'));}
 public function chatSend(Request $r,$id){$d=$r->validate(['body'=>'required|string|max:2000']);$c=DB::table('conversations')->where('id',$id)->first();abort_unless($c && (Auth::user()->role==='buyer'?$c->buyer_id==Auth::id():in_array(Auth::user()->role,['admin','employee']) && (Auth::user()->role==='admin'||Auth::user()->chat_enabled)),403);DB::table('messages')->insert(['conversation_id'=>$id,'sender_id'=>Auth::id(),'body'=>$d['body'],'created_at'=>now(),'updated_at'=>now()]);DB::table('conversations')->where('id',$id)->update(['last_message_at'=>now(),'updated_at'=>now()]);$target=Auth::user()->role==='buyer'?DB::table('users')->where('role','admin')->value('id'):$c->buyer_id;if($target)DB::table('notifications')->insert(['user_id'=>$target,'type'=>'chat','title'=>'Pesan chat baru','body'=>'Ada pesan baru dalam percakapan.','url'=>'/chat/'.$id,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function chatPoll($id){$c=DB::table('conversations')->where('id',$id)->first();abort_unless($c && (Auth::user()->role==='buyer'?$c->buyer_id==Auth::id():in_array(Auth::user()->role,['admin','employee'])),403);$msgs=DB::table('messages')->join('users','users.id','=','messages.sender_id')->where('conversation_id',$id)->where('messages.id','>',(int)request('after',0))->select('messages.id','messages.body','messages.created_at','messages.sender_id','users.name as sender')->orderBy('messages.id')->get();DB::table('messages')->where('conversation_id',$id)->where('sender_id','!=',Auth::id())->whereNull('read_at')->update(['read_at'=>now()]);return response()->json($msgs);}
 public function notifications(){ $items=DB::table('notifications')->where('user_id',Auth::id())->latest()->paginate(20);DB::table('notifications')->where('user_id',Auth::id())->whereNull('read_at')->update(['read_at'=>now()]);return view('notifications',compact('items')); }
 public function reports(){ $orders=DB::table('orders')->where('payment_status','paid')->count();$revenue=DB::table('orders')->where('payment_status','paid')->sum('total');$stock=DB::table('products')->sum('stock');$expired=DB::table('product_batches')->whereDate('expiry_date','<',today())->where('quantity','>',0)->count();return view('reports',compact('orders','revenue','stock','expired'));}

 public function returnsIndex(){ $q=DB::table('returns')->join('users','users.id','=','returns.user_id')->leftJoin('suppliers','suppliers.id','=','returns.supplier_id')->select('returns.*','users.name as requester','suppliers.name as supplier');if(Auth::user()->role==='employee')$q->where('returns.user_id',Auth::id());$items=$q->latest('returns.created_at')->paginate(15);return view('returns',compact('items')); }
 public function returnForm(){return view('return-form',['products'=>DB::table('products')->where('is_active',1)->get(),'batches'=>DB::table('product_batches')->where('quantity','>',0)->get()]);}
 public function saveReturn(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','batch_id'=>'nullable|exists:product_batches,id','quantity'=>'required|integer|min:1','reason'=>'required|string|max:1500']);$num='RT-'.now()->format('ymdHis').'-'.Str::upper(Str::random(3));$id=DB::table('returns')->insertGetId(['return_number'=>$num,'user_id'=>Auth::id(),'status'=>'pending','reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);$p=DB::table('products')->find($d['product_id']);DB::table('return_details')->insert(['return_id'=>$id,'product_id'=>$p->id,'batch_id'=>$d['batch_id']??null,'quantity'=>$d['quantity'],'unit_price'=>$p->purchase_price,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('admin.returns')->with('success','Pengajuan retur berhasil dikirim.');}
 public function decideReturn(Request $r,$id){abort_unless(Auth::user()->role==='admin',403);$d=$r->validate(['status'=>'required|in:approved,rejected','admin_note'=>'nullable|string|max:1000']);DB::transaction(function()use($id,$d){$ret=DB::table('returns')->where('id',$id)->lockForUpdate()->first();abort_unless($ret,404);if($ret->status!=='pending')return;DB::table('returns')->where('id',$id)->update(['status'=>$d['status'],'admin_note'=>$d['admin_note']??null,'approved_at'=>now(),'approved_by'=>Auth::id(),'updated_at'=>now()]);if($d['status']==='approved'){$lines=DB::table('return_details')->where('return_id',$id)->get();foreach($lines as $line){if($line->batch_id)DB::table('product_batches')->where('id',$line->batch_id)->decrement('quantity',$line->quantity);DB::table('products')->where('id',$line->product_id)->decrement('stock',$line->quantity);DB::table('stock_movements')->insert(['product_id'=>$line->product_id,'batch_id'=>$line->batch_id,'user_id'=>Auth::id(),'type'=>'return_out','quantity'=>-$line->quantity,'balance'=>DB::table('products')->where('id',$line->product_id)->value('stock'),'reference'=>$ret->return_number,'notes'=>'Retur disetujui','created_at'=>now(),'updated_at'=>now()]);}}});return back()->with('success','Keputusan retur disimpan.');}

 public function profile(){return view('profile');}
 public function updateProfile(Request $r){$d=$r->validate(['name'=>'required|max:120','phone'=>'nullable|max:30','address'=>'nullable|string']);DB::table('users')->where('id',Auth::id())->update($d+['updated_at'=>now()]);return back()->with('success','Profil diperbarui.');}
}
